public class Buch {
  String titel;
  String autor;
  int erscheinungsjahr;

  public Buch(String titel, String autor, int erscheinungsjahr) {
    this.titel = titel;
    this.autor = autor;
    this.erscheinungsjahr = erscheinungsjahr;
  }
}
